function withTimeout<T>(promise:Promise<T>,ms:number,message:string):Promise<T>{let timer:ReturnType<typeof setTimeout>|undefined;return Promise.race([promise,new Promise<T>((_,reject)=>{timer=setTimeout(()=>reject(new Error(message)),ms)})]).finally(()=>{if(timer)clearTimeout(timer)})}
const key="geerams-basket-v1";
function useServices(){const [items,setItems]=useState<Service[]>(starter);useEffect(()=>{if(!hasFirebaseWebConfig)return;return onSnapshot(collection(db,"services"),s=>{const allIds=new Set(s.docs.map(d=>d.id));const rows=s.docs.map(d=>({id:d.id,...d.data()} as Service)).filter(x=>x.active!==false&&starter.some(seed=>seed.id===x.id)&&cats.slice(1).includes(x.category));setItems([...rows,...starter.filter(seed=>!allIds.has(seed.id))])},()=>setItems(starter))},[]);return items}
function useBasket(){const [items,setItems]=useState<Line[]>([]);useEffect(()=>{try{setItems(JSON.parse(localStorage.getItem(key)||"[]"))}catch{setItems([])}},[]);function save(n:Line[]){setItems(n);try{localStorage.setItem(key,JSON.stringify(n))}catch{}}return {items,add:(s:Service)=>{const old=items.find(x=>x.serviceId===s.id);save(old?items.map(x=>x.serviceId===s.id?{...x,quantity:Math.min(99,x.quantity+1)}:x):[...items,{serviceId:s.id,name:s.name,category:s.category,price:s.price,quantity:1}])},remove:(id:string)=>save(items.filter(x=>x.serviceId!==id)),qty:(id:string,n:number)=>save(items.map(x=>x.serviceId===id?{...x,quantity:Math.min(99,n)}:x).filter(x=>x.quantity>0)),clear:()=>save([])}}
function Header({count=0,home=false}:{count?:number;home?:boolean}){return <><div className="af-topline"><span>KANYE, BOTSWANA · CLEANING PRODUCTS</span><span>Everyday cleaning. Bulk supply.</span></div><header className="af-header"><Link href="/" className="af-brand"><span className="af-brand-mark">G<span>✦</span></span><span><strong>GEERAMS</strong><small>— CLEANING SERVICES —</small></span></Link><nav>{!home&&<><Link href="/services">Shop products</Link><Link href="/#highlights">Product highlights</Link><Link href="/account">My orders</Link></>}</nav><div className="af-head-actions">{!home&&<Link className="af-basket-link" href="/basket">My basket <span>{count}</span></Link>}<Link className="af-button af-button-small" href="/services">Shop products ↗</Link></div></header></>}
